import math, sys
from fractions import Fraction as Fr
sys.path.insert(0,'/work/v4')
from data import Y, hits, area, foot, wilson, sp, hab, sz
A={h:Fr(str(area[h])) for h in hab}
def rnd(x,up):
    x=Fr(x).limit_denominator(10**9)
    f=x*100
    return Fr(math.ceil(f) if up else math.floor(f),100)
cells={}
for s in sp:
    L=[]
    for h in hab:
        for z in sz:
            lo,hi=wilson(hits[(s,z)],80)
            L.append(dict(y=Y[(s,h,z)],g=Fr(6*foot[h])/A[h],A=A[h],dlo=rnd(lo,False),dhi=rnd(hi,True)))
    cells[s]=L
def lit(q):
    q=Fr(q)
    return f"({q.numerator} / {q.denominator} : ℝ)" if q.denominator!=1 else f"({q.numerator} : ℝ)"
def meanR(y,r): return (y+1)*r/(1-r)+y
def varR(y,r): return (y+1)*r/(1-r)**2
def rLo(c,th,kl): return (1-1/(1+kl*c['A']))*(1-c['g']*th*c['dhi'])
def rHi(c,tl,kh): return (1-1/(1+kh*c['A']))*(1-c['g']*tl*c['dlo'])
def box(cs,tl,th,kl,kh):
    return (sum(meanR(c['y'],rLo(c,th,kl)) for c in cs), sum(meanR(c['y'],rHi(c,tl,kh)) for c in cs), sum(varR(c['y'],rHi(c,tl,kh)) for c in cs))
scen=[('full',Fr(1,4),Fr(1),Fr(1,20),Fr(5)),('tau1',Fr(1),Fr(1),Fr(1,20),Fr(5)),('tauhalf',Fr(1,2),Fr(1,2),Fr(1,20),Fr(5)),('tauquarter',Fr(1,4),Fr(1,4),Fr(1,20),Fr(5))]
groups=[('perchC',cells['perch']),('roachC',cells['roach']),('ruffeC',cells['ruffe']),('pikeC',cells['pike']),('lakeC',sum(cells.values(),[]))]
out={}
for name,tl,th,kl,kh in scen:
    for g,cs in groups:
        lo,hi,v=box(cs,tl,th,kl,kh)
        Lb=Fr(math.floor(lo)); Ub=Fr(math.ceil(hi)); Vb=Fr(math.ceil(v))
        c=Fr(math.ceil(math.sqrt(10*float(Vb))))
        while c*c<10*Vb: c+=1
        out[(name,g)]=dict(Lb=Lb,Ub=Ub,Vb=Vb,c=c,Lc=Lb-c,Uc=Ub+c,lo=float(lo),hi=float(hi),v=float(v))
if __name__=='__main__':
    for k,v in out.items(): print(k,{a:(round(b,1) if isinstance(b,float) else str(b)) for a,b in v.items()})
